def _fit(self, X):
    """Dispatch to the right submethod depending on the chosen solver."""
    xp, is_array_api_compliant = get_namespace(X)
    if issparse(X) and self.svd_solver not in ['auto', 'arpack', 'covariance_eigh']:
        raise TypeError(f'PCA only support sparse inputs with the "arpack" and "covariance_eigh" solvers, while "{self.svd_solver}" was passed. See TruncatedSVD for a possible alternative.')
    if self.svd_solver == 'arpack' and is_array_api_compliant:
        raise ValueError("PCA with svd_solver='arpack' is not supported for Array API inputs.")
    X = validate_data(self, X, dtype=[xp.float64, xp.float32], force_writeable=True, accept_sparse=('csr', 'csc'), ensure_2d=True, copy=False)
    self._fit_svd_solver = self.svd_solver
    if self._fit_svd_solver == 'auto' and issparse(X):
        self._fit_svd_solver = 'arpack'
    if self.n_components is None:
        if self._fit_svd_solver != 'arpack':
            n_components = min(X.shape)
        else:
            n_components = min(X.shape) - 1
    else:
        n_components = self.n_components
    if self._fit_svd_solver == 'auto':
        if X.shape[1] <= 1000 and X.shape[0] >= 10 * X.shape[1]:
            self._fit_svd_solver = 'covariance_eigh'
        elif max(X.shape) <= 500 or n_components == 'mle':
            self._fit_svd_solver = 'full'
        elif 1 <= n_components < 0.8 * min(X.shape):
            self._fit_svd_solver = 'randomized'
        else:
            self._fit_svd_solver = 'full'
    if self._fit_svd_solver in ('full', 'covariance_eigh'):
        return self._fit_full(X, n_components, xp, is_array_api_compliant)
    elif self._fit_svd_solver in ['arpack', 'randomized']:
        return self._fit_truncated(X, n_components, xp)

def _set_ticklabels(ax: Axes, labels: list[str], is_vertical: bool, **kwargs) -> None:
    """Set the tick labels of a given axis.

    Due to https://github.com/matplotlib/matplotlib/pull/17266, we need to handle the
    case of repeated ticks (due to `FixedLocator`) and thus we duplicate the number of
    labels.
    """
    ticks = ax.get_xticks() if is_vertical else ax.get_yticks()
    if len(ticks) != len(labels):
        i, remainder = divmod(len(ticks), len(labels))
        if Version(mpl.__version__) < Version('3.10'):
            assert remainder == 0, remainder
        labels *= i
    if is_vertical:
        ax.set_xticklabels(labels, **kwargs)
    else:
        ax.set_yticklabels(labels, **kwargs)

def requires_deep_recursion(func):
    """Decorator to skip test if deep recursion is not supported."""
    import pytest

    @wraps(func)
    def wrapper(*args, **kwargs):
        if IS_PYSTON:
            pytest.skip('Pyston disables recursion checking')
        if IS_WASM:
            pytest.skip('WASM has limited stack size')
        if not IS_64BIT:
            pytest.skip('32 bit Python has limited stack size')
        cflags = sysconfig.get_config_var('CFLAGS') or ''
        config_args = sysconfig.get_config_var('CONFIG_ARGS') or ''
        address_sanitizer = '-fsanitize=address' in cflags or '--with-address-sanitizer' in config_args
        thread_sanitizer = '-fsanitize=thread' in cflags or '--with-thread-sanitizer' in config_args
        if address_sanitizer or thread_sanitizer:
            pytest.skip('AddressSanitizer and ThreadSanitizer do not support deep recursion')
        return func(*args, **kwargs)
    return wrapper

def __mul__(self, other):
    """Multiply self by other, and return a new masked array."""
    if self._delegate_binop(other):
        return NotImplemented
    return multiply(self, other)

def save_to_buffer(string: str, buf: FilePath | WriteBuffer[str] | None=None, encoding: str | None=None) -> str | None:
    """
    Perform serialization. Write to buf or return as string if buf is None.
    """
    with _get_buffer(buf, encoding=encoding) as fd:
        fd.write(string)
        if buf is None:
            return fd.getvalue()
        return None

def _update_strl_names(self) -> None:
