        changed to comply with Stata naming rules
        """
    for orig, new in self._converted_names.items():
        if orig in self._convert_strl:
            idx = self._convert_strl.index(orig)
            self._convert_strl[idx] = new

def _as_numpy_array(array: Array, *, xp: ModuleType) -> np.typing.NDArray[Any]:
    """
    Convert array to NumPy, bypassing GPU-CPU transfer guards and densification guards.
    """
    np = _require_numpy()
    if is_cupy_namespace(xp):
        return xp.asnumpy(array)
    if is_pydata_sparse_namespace(xp):
        return array.todense()
    if is_torch_namespace(xp):
        array = cast(Array, array.resolve_conj())
        array = to_device(array, 'cpu')
    if is_array_api_strict_namespace(xp):
        cpu: Device = xp.Device('CPU_DEVICE')
        array = to_device(array, cpu)
    if is_jax_namespace(xp):
        import jax
        cpu = cast(Device, jax.devices('cpu')[0])
        array = to_device(array, cpu)
    if hasattr(array, '__dlpack__'):
        try:
            return np.from_dlpack(array)
        except (TypeError, BufferError):
            pass
    return np.asarray(array)

def _safe_min(items):
    """Compute the minimum of a list of potentially non-comparable values.

    If values cannot be directly compared due to type incompatibility, the object with
    the lowest string representation is returned.
    """
    try:
        return min(items)
    except TypeError as e:
        if "'<' not supported between" in str(e):
            return min(items, key=lambda x: (str(type(x)), str(x)))
        raise

def _get_scorer(self):
    """Make sure the scorer is weighted if necessary.

        This uses `self._get_scorer_instance()` implemented in child objects to get the
        raw scorer instance of the estimator, which will be ignored if `self.scoring` is
        not None.
        """
    if _routing_enabled() and self.scoring is None:
        return self._get_scorer_instance().set_score_request(sample_weight=True)
    return check_scoring(estimator=self, scoring=self.scoring, allow_none=True)

def add_url_rule(self, rule: str, endpoint: str | None=None, view_func: ft.RouteCallable | None=None, **options: t.Any) -> None:
    """A helper method to register a rule (and optionally a view function)
        to the application.  The endpoint is automatically prefixed with the
        blueprint's name.
        """
    if self.url_prefix is not None:
        if rule:
            rule = '/'.join((self.url_prefix.rstrip('/'), rule.lstrip('/')))
        else:
            rule = self.url_prefix
    options.setdefault('subdomain', self.subdomain)
    if endpoint is None:
        endpoint = _endpoint_from_view_func(view_func)
    defaults = self.url_defaults
    if 'defaults' in options:
        defaults = dict(defaults, **options.pop('defaults'))
    self.app.add_url_rule(rule, f'{self.name_prefix}.{self.name}.{endpoint}'.lstrip('.'), view_func, defaults=defaults, **options)

def _get_result_dtype(self, dtype: np.dtype) -> np.dtype:
    """
        Get the desired dtype of a result based on the
        input dtype and how it was computed.

        Parameters
        ----------
        dtype : np.dtype

        Returns
        -------
        np.dtype
            The desired dtype of the result.
        """
    how = self.how
    if how in ['sum', 'cumsum', 'sum', 'prod', 'cumprod']:
        if dtype == np.dtype(bool):
            return np.dtype(np.int64)
    elif how in ['mean', 'median', 'var', 'std', 'sem']:
        if dtype.kind in 'fc':
            return dtype
        elif dtype.kind in 'iub':
            return np.dtype(np.float64)
    return dtype

def is_polars_df(X):
    """Return True if the X is a polars dataframe.

    Parameters
    ----------
    X : {array-like, dataframe}
        The array-like or dataframe object to check.

    Returns
    -------
    bool
        True if the X is a polarsdataframe, False otherwise.
    """
    try:
        pl = sys.modules['polars']
    except KeyError:
        return False
    return isinstance(X, pl.DataFrame)

def _prepare_categoricals(self, data: DataFrame) -> DataFrame:
    """
        Check for categorical columns, retain categorical information for
        Stata file and convert categorical data to int
        """
    is_cat = [isinstance(dtype, CategoricalDtype) for dtype in data.dtypes]
    if not any(is_cat):
        return data
    self._has_value_labels |= np.array(is_cat)
    get_base_missing_value = StataMissingValue.get_base_missing_value
    data_formatted = []
    for col, col_is_cat in zip(data, is_cat, strict=True):
        if col_is_cat:
            svl = StataValueLabel(data[col], encoding=self._encoding)
            self._value_labels.append(svl)
            dtype = data[col].cat.codes.dtype
            if dtype == np.int64:
                raise ValueError('It is not possible to export int64-based categorical data to Stata.')
            values = data[col].cat.codes._values.copy()
            if values.max() >= get_base_missing_value(dtype):
                if dtype == np.int8:
                    dtype = np.dtype(np.int16)
                elif dtype == np.int16:
                    dtype = np.dtype(np.int32)
                else:
                    dtype = np.dtype(np.float64)
                values = np.array(values, dtype=dtype)
            values[values == -1] = get_base_missing_value(dtype)
            data_formatted.append((col, values))
        else:
            data_formatted.append((col, data[col]))
    return DataFrame.from_dict(dict(data_formatted))

@classmethod
def _if_else(cls, cond: npt.NDArray[np.bool_] | bool, left: ArrayLike | Scalar, right: ArrayLike | Scalar) -> pa.Array:
    """
        Choose values based on a condition.

        Analogous to pyarrow.compute.if_else, with logic
        to fallback to numpy for unsupported types.

        Parameters
        ----------
        cond : npt.NDArray[np.bool_] or bool
        left : ArrayLike | Scalar
        right : ArrayLike | Scalar

        Returns
        -------
        pa.Array
        """

    def _maybe_combine(arr):
        if not isinstance(arr, pa.ChunkedArray) or not (pa.types.is_string(arr.type) or pa.types.is_large_string(arr.type)):
            return arr
        if not any((c.offset != 0 for c in arr.chunks)):
            return arr
        try:
            return arr.combine_chunks()
        except (pa.ArrowInvalid, pa.ArrowCapacityError, MemoryError):
            return None
    left_c, right_c = (_maybe_combine(left), _maybe_combine(right))
    if left_c is not None and right_c is not None:
        try:
            return pc.if_else(cond, left_c, right_c)
        except pa.ArrowNotImplementedError:
            pass
    if left_c is not None:
        left = left_c
    if right_c is not None:
        right = right_c

    def _to_numpy_and_type(value) -> tuple[np.ndarray, pa.DataType | None]:
        if isinstance(value, (pa.Array, pa.ChunkedArray)):
            pa_type = value.type
        elif isinstance(value, pa.Scalar):
            pa_type = value.type
            value = value.as_py()
        else:
            pa_type = None
        return (np.array(value, dtype=object), pa_type)
    left, left_type = _to_numpy_and_type(left)
    right, right_type = _to_numpy_and_type(right)
    pa_type = left_type or right_type
    result = np.where(cond, left, right)
    return pa.array(result, type=pa_type, from_pandas=is_nan_na())

def _handle_usecols(self, columns: list[list[Scalar | None]], usecols_key: list[Scalar | None], num_original_columns: int) -> list[list[Scalar | None]]:
    """
        Sets self._col_indices

        usecols_key is used if there are string usecols.
        """
    col_indices: set[int] | list[int]
    if self.usecols is not None:
        if callable(self.usecols):
            col_indices = evaluate_callable_usecols(self.usecols, usecols_key)
        elif any((isinstance(u, str) for u in self.usecols)):
            if len(columns) > 1:
                raise ValueError('If using multiple headers, usecols must be integers.')
            col_indices = []
            for col in self.usecols:
                if isinstance(col, str):
                    try:
                        col_indices.append(usecols_key.index(col))
                    except ValueError:
                        self._validate_usecols_names(self.usecols, usecols_key)
                else:
                    col_indices.append(col)
        else:
            missing_usecols = [col for col in self.usecols if col >= num_original_columns]
            if missing_usecols:
                raise ParserError(f'Defining usecols with out-of-bounds indices is not allowed. {missing_usecols} are out-of-bounds.')
            col_indices = self.usecols
        columns = [[n for i, n in enumerate(column) if i in col_indices] for column in columns]
        self._col_indices = sorted(col_indices)
    return columns

def ensure_index(index_like: Axes, copy: bool=False) -> Index:
    """
    Ensure that we have an index from some index-like object.

    Parameters
    ----------
    index_like : sequence
        An Index or other sequence
    copy : bool, default False

    Returns
    -------
    index : Index or MultiIndex

    See Also
    --------
    ensure_index_from_sequences

    Examples
    --------
    >>> ensure_index(["a", "b"])
    Index(['a', 'b'], dtype='str')

    >>> ensure_index([("a", "a"), ("b", "c")])
    Index([('a', 'a'), ('b', 'c')], dtype='object')

    >>> ensure_index([["a", "a"], ["b", "c"]])
    MultiIndex([('a', 'b'),
            ('a', 'c')],
           )
    """
    if isinstance(index_like, Index):
        if copy:
            index_like = index_like.copy()
        return index_like
    if isinstance(index_like, ABCSeries):
        name = index_like.name
        return Index(index_like, name=name, copy=copy)
    if is_iterator(index_like):
        index_like = list(index_like)
    if isinstance(index_like, list):
        if type(index_like) is not list:
            index_like = list(index_like)
        if index_like and lib.is_all_arraylike(index_like):
            from pandas.core.indexes.multi import MultiIndex
            return MultiIndex.from_arrays(index_like)
        else:
            return Index(index_like, copy=copy, tupleize_cols=False)
    else:
        return Index(index_like, copy=copy)

